    "clinicalCase": "Paciente do sexo masculino, 30 anos, é atendido no serviço de urgência de hospital terciário após acidente automobilístico com capotamento do carro. O paciente se encontra respirando espontaneamente; frequência cardíaca de 95 bpm; pressão arterial de 130 x 88 mmHg; escala de coma de Glasgow de 15; não está sob efeito de álcool ou drogas. Exame físico de cabeça, pescoço e tórax sem alterações. Durante avaliação secundária, nota-se que o paciente não apresenta movimentos em membros inferiores. Também há perda completa da sensibilidade tátil e dolorosa nesses membros, perda essa que se estende até o nível da cicatriz umbilical. Considerando esse quadro clínico, qual é o nível da lesão medular?",
