    "clinicalCase": "Homem de 50 anos apresentou-se ao serviço de emergência após episódio de hematêmese. Relata história de 3 meses de dor epigástrica e diarreia fétida, amarelada, pastosa, com algumas gotas de gordura, e perda de peso significativa. Histórico de ingestão de 500 mL de bebida alcoólica destilada, por dia, durante 15 anos. Exame físico: paciente emagrecido, índice de massa corporal de 17 kg/m²; temperatura axilar de 36,5 °C; mucosas hipocoradas ++/4+; hidratadas; ictéricas +/4+; aparelho respiratório sem alterações; aparelho cardiovascular com bulhas rítmicas e hiperfonéticas; frequência cardíaca de 87 bpm; pressão arterial de 120 x 80 mmHg; abdome pouco distendido, com sensibilidade à palpação epigástrica e ruídos hidroaéreos normais. Os resultados dos testes laboratoriais, incluindo lipase sérica e testes de função hepática, estavam dentro dos limites normais. A tomografia computadorizada do abdome mostrou extensa calcificação do pâncreas, sem evidência de edema pancreático ou presença de líquido peripancreático. A endoscopia digestiva alta revelou enantema em antro. De acordo com o quadro clínico, o exame físico e os exames complementares, qual é a conduta mais adequada?",
